/**
 * Test flow for updateMultipleRecords action
 * Demonstrates updating multiple records at once
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testUpdateMultipleRecords = Flow(
    {
        $id: Now.ID['test_update_multiple_records_flow'],
        name: 'Test Update Multiple Records',
        description: 'Tests the updateMultipleRecords core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_update_multiple_records_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.updateMultipleRecords,
            { $id: Now.ID['test_update_multiple_records_action'] },
            {
                table_name: 'incident',
                conditions: 'active=true^priority=3^assigned_to=NULL',
                field_values: TemplateValue({ state: '2', comments: 'Bulk updated by flow' }),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_update_multiple_records_log'] },
            {
                log_level: 'info',
                log_message: `updateMultipleRecords outputs: count=${wfa.dataPill(result.count, 'integer')}, status=${wfa.dataPill(result.status, 'string')}, error_message=${wfa.dataPill(result.message, 'string')}`,
            }
        )
    }
)
